// Mesh Gradient — plugin main thread. The UI panel (ui.html, generated by
// build_plugin.py) is a full editor running the shared WebGL engine; this side
// does all Figma document work: read/apply fills, image fills, variables, and
// preset persistence.

figma.showUI(__html__, { width: 380, height: 610, themeColors: true });

const PRESET_KEY = 'mesh-gradient.presets';
const SHADER_MAP_KEY = 'mesh-gradient.shader-map';
const VAR_LINK_KEY = 'mesh-gradient.linked-collection';

// Pick a collection's Light/Dark modes by name. When a collection has no
// light/dark-named modes (e.g. a brand-theme or single-mode collection), both
// fall back to its DEFAULT mode — never an arbitrary other mode.
function lightDarkModes(col) {
  const def = col.modes.find((m) => m.modeId === col.defaultModeId) || col.modes[0];
  const light = col.modes.find((m) => /light/i.test(m.name)) || def;
  const dark = col.modes.find((m) => /dark/i.test(m.name)) || def;
  return { light, dark };
}

// Resolve a variable's COLOR value for a mode, following aliases across
// collections (matching mode by name at each hop).
async function resolveColor(variable, modeKind, depth) {
  if (!variable || (depth || 0) > 8) return null;
  const col = await figma.variables.getVariableCollectionByIdAsync(variable.variableCollectionId);
  if (!col) return null;
  const mode = lightDarkModes(col)[modeKind];
  const value = variable.valuesByMode[mode.modeId];
  if (value && value.type === 'VARIABLE_ALIAS') {
    const next = await figma.variables.getVariableByIdAsync(value.id);
    return resolveColor(next, modeKind, (depth || 0) + 1);
  }
  if (value && typeof value.r === 'number') return { r: value.r, g: value.g, b: value.b };
  return null;
}

// A collection's COLOR variables, in collection order.
async function colorVariablesOf(col) {
  const vars = await Promise.all(col.variableIds.map((id) => figma.variables.getVariableByIdAsync(id)));
  return vars.filter((v) => v && v.resolvedType === 'COLOR');
}

function reply(msg) { figma.ui.postMessage(msg); }
function status(ok, error) { reply({ type: 'status', ok, error }); }

function fillableSelection() {
  return figma.currentPage.selection.filter((n) => 'fills' in n);
}

function hexToRgba(hex) {
  const n = parseInt(hex.replace('#', ''), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255, a: 1 };
}

figma.ui.onmessage = async (msg) => {
  // ---- presets (clientStorage) ---------------------------------------------
  if (msg.type === 'get-presets') {
    const presets = (await figma.clientStorage.getAsync(PRESET_KEY)) || {};
    reply({ type: 'presets', presets });

  } else if (msg.type === 'save-presets') {
    await figma.clientStorage.setAsync(PRESET_KEY, msg.presets || {});

  // ---- variable collection link --------------------------------------------
  // Collections can be LOCAL (defined in this file) or LIBRARY (published from
  // another file — how token setups usually arrive). Library variables are
  // invisible to the local API; they're enumerated via teamLibrary and
  // imported on pull. Linked ids are prefixed 'local:' / 'lib:'.
  } else if (msg.type === 'get-collections') {
    try {
      const list = [];
      const collections = await figma.variables.getLocalVariableCollectionsAsync();
      for (const col of collections) {
        const colorVars = await colorVariablesOf(col);
        if (colorVars.length) list.push({ id: 'local:' + col.id, name: col.name, colorCount: colorVars.length });
      }
      try {
        const libCols = await figma.teamLibrary.getAvailableLibraryVariableCollectionsAsync();
        for (const lc of libCols) {
          const libVars = await figma.teamLibrary.getVariablesInLibraryCollectionAsync(lc.key);
          const colorCount = libVars.filter((v) => v.resolvedType === 'COLOR').length;
          if (colorCount) {
            list.push({ id: 'lib:' + lc.key, name: lc.name + ' — ' + lc.libraryName, colorCount });
          }
        }
      } catch (e) { /* team library unavailable (e.g. drafts) — locals still listed */ }
      const linkedId = (await figma.clientStorage.getAsync(VAR_LINK_KEY)) || null;
      reply({ type: 'collections', list, linkedId });
      if (!list.length) status(null, 'No color-variable collections found (local or library) in this file.');
    } catch (e) {
      status(null, 'Listing variables failed: ' + e.message);
    }

  } else if (msg.type === 'link-collection') {
    await figma.clientStorage.setAsync(VAR_LINK_KEY, msg.collectionId || null);

  } else if (msg.type === 'pull-variables') {
    try {
      const linkedId = await figma.clientStorage.getAsync(VAR_LINK_KEY);
      if (!linkedId) return status(null, 'Link a collection first.');
      let colorVars = [];
      if (linkedId.indexOf('lib:') === 0) {
        const key = linkedId.slice(4);
        const libVars = await figma.teamLibrary.getVariablesInLibraryCollectionAsync(key);
        const colorLibVars = libVars.filter((v) => v.resolvedType === 'COLOR').slice(0, 16);
        for (const lv of colorLibVars) {
          colorVars.push(await figma.variables.importVariableByKeyAsync(lv.key));
        }
      } else {
        const id = linkedId.indexOf('local:') === 0 ? linkedId.slice(6) : linkedId; // legacy unprefixed = local
        const col = await figma.variables.getVariableCollectionByIdAsync(id);
        if (!col) return status(null, 'Linked collection not found — pick one again.');
        colorVars = (await colorVariablesOf(col)).slice(0, 16);
      }
      if (!colorVars.length) return status(null, 'No color variables in that collection.');
      const palette = [];
      for (const v of colorVars) {
        palette.push({
          name: v.name,
          light: await resolveColor(v, 'light'),
          dark: await resolveColor(v, 'dark'),
        });
      }
      reply({ type: 'variables-pulled', palette });
    } catch (e) {
      status(null, 'Pull failed: ' + e.message);
    }

  // ---- custom shader targeting ---------------------------------------------
  } else if (msg.type === 'get-shader-map') {
    const map = (await figma.clientStorage.getAsync(SHADER_MAP_KEY)) || null;
    reply({ type: 'shader-map', map });

  } else if (msg.type === 'save-shader-map') {
    await figma.clientStorage.setAsync(SHADER_MAP_KEY, msg.map || null);

  } else if (msg.type === 'capture-shader') {
    const node = figma.currentPage.selection.find(
      (n) => 'fills' in n && Array.isArray(n.fills) && n.fills.some((f) => f.type === 'SHADER')
    );
    if (!node) return status(null, 'Select a layer filled with your custom shader first.');
    const shader = node.fills.find((f) => f.type === 'SHADER');
    reply({ type: 'shader-captured', id: shader.id, properties: shader.properties });

  // ---- import the selected mesh (with a PNG reference for refinement) ------
  } else if (msg.type === 'import-selection') {
    const node = figma.currentPage.selection.find(
      (n) => 'fills' in n && Array.isArray(n.fills) && n.fills.some((f) => f.type === 'SHADER')
    );
    if (!node) return status(null, 'Select a layer with a mesh gradient fill.');
    const shader = node.fills.find((f) => f.type === 'SHADER');
    let refBytes = null;
    try {
      refBytes = await node.exportAsync({
        format: 'PNG',
        constraint: { type: 'WIDTH', value: 320 },
      });
    } catch (e) { /* refinement is optional */ }
    reply({
      type: 'selection-mesh',
      properties: shader.properties,
      width: node.width,
      height: node.height,
      refBytes,
    });

  // ---- apply as native mesh shader fill ------------------------------------
  } else if (msg.type === 'apply-shader') {
    const targets = fillableSelection();
    if (!targets.length) return status(null, 'Select a frame or shape first.');
    try {
      targets.forEach((n) => { n.fills = [msg.paint]; });
      figma.notify('Mesh gradient applied to ' + targets.length + ' layer(s)');
      status('Applied mesh fill to ' + targets.length + ' layer(s).');
    } catch (e) {
      status(null, 'Apply failed: ' + e.message);
    }

  // ---- apply the paused frame as an image fill ------------------------------
  } else if (msg.type === 'image-size-request') {
    const target = fillableSelection()[0];
    if (!target) return status(null, 'Select a frame or shape first.');
    reply({ type: 'image-size', width: Math.round(target.width), height: Math.round(target.height) });

  } else if (msg.type === 'apply-image') {
    const targets = fillableSelection();
    if (!targets.length) return status(null, 'Selection changed — select the target again.');
    try {
      const image = figma.createImage(new Uint8Array(msg.bytes));
      targets.forEach((n) => {
        n.fills = [{ type: 'IMAGE', imageHash: image.hash, scaleMode: 'FILL' }];
      });
      figma.notify('Frame applied as image fill');
      status('Paused frame applied as image fill.');
    } catch (e) {
      status(null, 'Image fill failed: ' + e.message);
    }

  // ---- create/update Light/Dark variables ----------------------------------
  // Writes to the LINKED collection when one is set (index-mapped onto its
  // color variables, creating extras if it has fewer than the palette).
  // With no link, creates/updates a local "Mesh Gradient" collection.
  } else if (msg.type === 'make-variables') {
    try {
      let col = null;
      const linkedId = await figma.clientStorage.getAsync(VAR_LINK_KEY);
      if (linkedId && linkedId.indexOf('lib:') === 0) {
        return status(null, 'The linked collection is a published library — edit its variables in the library file itself. (Pull works here; Push can’t write across files.)');
      }
      if (linkedId) {
        const id = linkedId.indexOf('local:') === 0 ? linkedId.slice(6) : linkedId;
        col = await figma.variables.getVariableCollectionByIdAsync(id);
      }
      if (!col) {
        const collections = await figma.variables.getLocalVariableCollectionsAsync();
        col = collections.find((c) => c.name === 'Mesh Gradient');
        if (!col) {
          col = figma.variables.createVariableCollection('Mesh Gradient');
          col.renameMode(col.modes[0].modeId, 'Light');
          col.addMode('Dark');
        }
      }
      const modes = lightDarkModes(col);
      if (modes.light.modeId === modes.dark.modeId && col.modes.length === 1) {
        try { modes.dark = { modeId: col.addMode('Dark'), name: 'Dark' }; } catch (e) { /* mode limit */ }
      }
      const colorVars = await colorVariablesOf(col);
      for (let i = 0; i < msg.palette.length; i++) {
        const item = msg.palette[i];
        let v = colorVars[i];
        if (!v) {
          v = figma.variables.createVariable(item.name, col, 'COLOR');
          v.scopes = ['FRAME_FILL', 'SHAPE_FILL'];
        }
        v.setValueForMode(modes.light.modeId, hexToRgba(item.light));
        if (modes.dark.modeId !== modes.light.modeId) v.setValueForMode(modes.dark.modeId, hexToRgba(item.dark));
      }
      figma.notify('Variables updated in "' + col.name + '" (' + msg.palette.length + ')');
      status('Pushed ' + msg.palette.length + ' colors × Light/Dark to "' + col.name + '".');
    } catch (e) {
      status(null, 'Variables failed: ' + e.message);
    }
  }
};
